INSERT INTO products (name, slug, description, short_description, category_id, brand_id, sku, price, compare_at_price, images, primary_image, specifications, features, whats_included, compatibility, tags, rating, review_count, stock, is_featured, is_bestseller, is_new_arrival, is_deal, weight) VALUES
('HC-SR04 Ultrasonic Distance Sensor', 'hc-sr04-ultrasonic-sensor', 'The HC-SR04 is an ultrasonic distance sensor that provides 2cm to 400cm non-contact measurement with ranging accuracy of 3mm. Perfect for obstacle avoidance in robots and distance measurement projects.', 'Ultrasonic distance sensor for robotics', (SELECT id FROM categories WHERE slug='sensors'), (SELECT id FROM brands WHERE slug='hiletgo'), 'SEN-HCSR04', 149.00, 249.00, ARRAY['https://images.pexels.com/photos/35686444/pexels-photo-35686444.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686436/pexels-photo-35686436.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686438/pexels-photo-35686438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686444/pexels-photo-35686444.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Operating Voltage":"5V DC","Operating Current":"15 mA","Operating Frequency":"40 kHz","Max Range":"4 m","Min Range":"2 cm","Measuring Angle":"15 degrees","Trigger Input Pulse":"10 us TTL","Dimensions":"45 x 20 x 15 mm","Weight":"9 g"}'::jsonb, ARRAY['2cm to 400cm range','3mm accuracy','5V operation','15 degree measuring angle','Easy to interface'], ARRAY['1x HC-SR04 Sensor','1x Mounting Bracket'], ARRAY['Arduino','ESP32','Raspberry Pi','PIC','STM32'], ARRAY['sensor','ultrasonic','distance','robotics','obstacle detection'], 4.6, 156, 500, false, true, false, true, 9),
('DHT22 Temperature and Humidity Sensor', 'dht22-temp-humidity-sensor', 'The DHT22 is a basic, low-cost digital temperature and humidity sensor. It uses a capacitive humidity sensor and a thermistor to measure the surrounding air. Temperature accuracy of plus or minus 0.5C and humidity accuracy of plus or minus 2%.', 'Digital temperature and humidity sensor module', (SELECT id FROM categories WHERE slug='sensors'), (SELECT id FROM brands WHERE slug='adafruit'), 'SEN-DHT22', 249.00, 399.00, ARRAY['https://images.pexels.com/photos/35686438/pexels-photo-35686438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686432/pexels-photo-35686432.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686444/pexels-photo-35686444.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686438/pexels-photo-35686438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Temperature Range":"-40 to 80 C","Temperature Accuracy":"+/- 0.5 C","Humidity Range":"0-100% RH","Humidity Accuracy":"+/- 2% RH","Output":"Digital signal","Power Supply":"3.3-6V DC","Sampling Period":"2 seconds","Dimensions":"15.1 x 12 x 5.5 mm","Weight":"3 g"}'::jsonb, ARRAY['-40 to 80C temperature range','0-100% RH humidity range','High accuracy','Digital output','Low power'], ARRAY['1x DHT22 Sensor','1x 4.7K pull-up resistor'], ARRAY['Arduino','ESP32','Raspberry Pi','PIC','STM32'], ARRAY['sensor','temperature','humidity','dht22','weather station','iot'], 4.5, 112, 350, false, true, false, false, 3),
('IR Infrared Obstacle Avoidance Sensor Module', 'ir-obstacle-sensor-module', 'An infrared obstacle avoidance sensor module with adjustable detection distance. Features an IR transmitter and receiver pair, potentiometer for distance adjustment, and digital output. Ideal for line following and obstacle avoidance robots.', 'Adjustable IR obstacle detection sensor', (SELECT id FROM categories WHERE slug='sensors'), (SELECT id FROM brands WHERE slug='hiletgo'), 'SEN-IR-OBS', 79.00, 149.00, ARRAY['https://images.pexels.com/photos/35686444/pexels-photo-35686444.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686436/pexels-photo-35686436.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686430/pexels-photo-35686430.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686444/pexels-photo-35686444.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Operating Voltage":"3.3-5V","Detection Distance":"2-30 cm (adjustable)","Output Type":"Digital (HIGH/LOW)","Current":"20 mA","Frequency":"38 kHz","Dimensions":"48 x 14 x 12 mm","Weight":"5 g"}'::jsonb, ARRAY['Adjustable detection distance','Digital output','3.3-5V operation','Low cost','Easy to interface'], ARRAY['1x IR Sensor Module','1x 3-pin header'], ARRAY['Arduino','ESP32','Raspberry Pi','PIC'], ARRAY['sensor','ir','infrared','obstacle','robotics','line follower'], 4.3, 56, 600, false, false, false, false, 5),
('MPU6050 6-Axis Gyroscope Accelerometer Module', 'mpu6050-gyro-accel', 'The MPU6050 is a 6-axis motion tracking device combining a 3-axis gyroscope and 3-axis accelerometer. Features I2C interface, built-in DMP, and programmable interrupt. Perfect for drone stabilization, robotics, and motion sensing projects.', '6-axis gyroscope + accelerometer with I2C', (SELECT id FROM categories WHERE slug='sensors'), (SELECT id FROM brands WHERE slug='adafruit'), 'SEN-MPU6050', 199.00, 349.00, ARRAY['https://images.pexels.com/photos/35686438/pexels-photo-35686438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686432/pexels-photo-35686432.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686444/pexels-photo-35686444.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686438/pexels-photo-35686438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Gyroscope Range":"+/- 250, 500, 1000, 2000 deg/s","Accelerometer Range":"+/- 2g, 4g, 8g, 16g","Interface":"I2C","I2C Address":"0x68","Operating Voltage":"3.3-5V","DMP":"Yes (Digital Motion Processor)","Dimensions":"20 x 15 x 2 mm","Weight":"2 g"}'::jsonb, ARRAY['3-axis gyroscope + 3-axis accelerometer','I2C interface','Built-in DMP','Programmable interrupt','3.3-5V compatible'], ARRAY['1x MPU6050 Module','1x Header pins'], ARRAY['Arduino','ESP32','Raspberry Pi','PIC','STM32'], ARRAY['sensor','gyroscope','accelerometer','mpu6050','drone','robotics','imu'], 4.6, 112, 250, false, true, false, false, 2),
('HC-SR501 PIR Motion Sensor Module', 'pir-motion-sensor-hc-sr501', 'The HC-SR501 is a PIR (Passive Infrared) motion sensor module with adjustable sensitivity and delay. Detects human movement within a 7 meter range and 120 degree angle. Perfect for security, lighting, and automation projects.', 'Adjustable PIR motion sensor for security', (SELECT id FROM categories WHERE slug='sensors'), (SELECT id FROM brands WHERE slug='hiletgo'), 'SEN-PIR-501', 99.00, 199.00, ARRAY['https://images.pexels.com/photos/35686444/pexels-photo-35686444.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686438/pexels-photo-35686438.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686444/pexels-photo-35686444.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Detection Range":"7 meters","Detection Angle":"120 degrees","Delay Time":"5-200 seconds (adjustable)","Trigger":"Adjustable","Operating Voltage":"4.5-20V","Output":"3.3V HIGH / 0V LOW","Dimensions":"32 x 24 x 18 mm","Weight":"7 g"}'::jsonb, ARRAY['7 meter detection range','120 degree angle','Adjustable sensitivity and delay','3.3V digital output','Low power consumption'], ARRAY['1x HC-SR501 PIR Sensor'], ARRAY['Arduino','ESP32','Raspberry Pi','NodeMCU'], ARRAY['sensor','pir','motion','security','automation','home automation'], 4.5, 89, 400, false, true, false, false, 7),
('L298N Dual H-Bridge Motor Driver', 'l298n-motor-driver', 'The L298N is a dual H-Bridge motor driver that allows speed and direction control of two DC motors or one stepper motor. Can drive motors up to 35V at 2A per coil.', 'Dual H-bridge for DC/stepper motor control', (SELECT id FROM categories WHERE slug='motor-drivers'), (SELECT id FROM brands WHERE slug='hiletgo'), 'MOT-L298N', 299.00, 499.00, ARRAY['https://images.pexels.com/photos/5276099/pexels-photo-5276099.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686430/pexels-photo-35686430.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686442/pexels-photo-35686442.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/5276099/pexels-photo-5276099.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Driver Chip":"L298N","Operating Voltage":"5-35V","Logic Voltage":"5V","Max Continuous Current":"2A per channel","Max Peak Current":"3A per channel","Channels":"2","Drive Type":"Dual H-Bridge","Dimensions":"43 x 43 x 27 mm","Weight":"30 g"}'::jsonb, ARRAY['Dual H-bridge driver','5-35V motor voltage','2A per channel','PWM speed control','Built-in 5V regulator'], ARRAY['1x L298N Module'], ARRAY['Arduino','ESP32','Raspberry Pi','STM32'], ARRAY['motor driver','l298n','h-bridge','dc motor','robotics'], 4.5, 98, 300, false, true, false, false, 30),
('SG90 Micro Servo Motor 9g', 'sg90-micro-servo', 'The SG90 is a tiny and lightweight servo motor that can rotate approximately 180 degrees (90 in each direction). Perfect for small robot arms, RC vehicles, and automation projects.', '9g micro servo for robotics and RC projects', (SELECT id FROM categories WHERE slug='motors'), (SELECT id FROM brands WHERE slug='elegoo'), 'MOT-SG90', 99.00, 179.00, ARRAY['https://images.pexels.com/photos/35686432/pexels-photo-35686432.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686448/pexels-photo-35686448.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686439/pexels-photo-35686439.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686432/pexels-photo-35686432.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Weight":"9g","Dimensions":"22.2 x 11.8 x 31 mm","Stall Torque":"1.8 kg-cm (4.8V)","Operating Speed":"0.1s/60 degree (4.8V)","Operating Voltage":"4.8-6V","Temperature Range":"0 to 55 C","Rotation":"0-180 degrees","Gear Type":"Nylon"}'::jsonb, ARRAY['180 degree rotation','1.8 kg-cm torque','Lightweight 9g design','Nylon gears','4.8-6V operation'], ARRAY['1x SG90 Servo Motor','3x Horns','1x Mounting hardware set'], ARRAY['Arduino','ESP32','Raspberry Pi','RC receivers'], ARRAY['servo','motor','robotics','sg90','micro servo'], 4.4, 87, 400, false, true, false, true, 9),
('NEMA 17 Stepper Motor 42BYG', 'nema17-stepper-motor', 'NEMA 17 stepper motor with 1.8 degree step angle, 1.5A current, and 4-wire connection. Perfect for 3D printers, CNC machines, and precision positioning applications.', 'NEMA 17 bipolar stepper motor for CNC/3D printing', (SELECT id FROM categories WHERE slug='motors'), (SELECT id FROM brands WHERE slug='dfrobot'), 'MOT-NEMA17', 899.00, 1299.00, ARRAY['https://images.pexels.com/photos/11579194/pexels-photo-11579194.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686432/pexels-photo-35686432.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/11579194/pexels-photo-11579194.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Step Angle":"1.8 degrees","Holding Torque":"4.8 kg-cm","Rated Current":"1.5A","Phase Resistance":"2.1 ohm","Phase Inductance":"3.2 mH","Number of Phases":"4","Frame Size":"42 x 42 mm (NEMA 17)","Body Length":"40 mm","Shaft Diameter":"5 mm","Weight":"350 g"}'::jsonb, ARRAY['1.8 degree step angle','4.8 kg-cm holding torque','NEMA 17 standard size','4-wire bipolar','Low noise'], ARRAY['1x NEMA 17 Stepper Motor'], ARRAY['A4988 Driver','DRV8825 Driver','TMC2209 Driver','Arduino','Raspberry Pi'], ARRAY['stepper motor','nema17','cnc','3d printer','precision'], 4.7, 67, 100, false, true, false, false, 350),
('A4988 Stepper Motor Driver Module', 'a4988-stepper-driver', 'The A4988 is a complete stepper motor driver module with built-in translator for easy operation. Can drive bipolar stepper motors up to 2A per coil. Perfect for 3D printers and CNC machines.', 'Stepper motor driver with built-in translator', (SELECT id FROM categories WHERE slug='motor-drivers'), (SELECT id FROM brands WHERE slug='hiletgo'), 'MOT-A4988', 199.00, 349.00, ARRAY['https://images.pexels.com/photos/5276099/pexels-photo-5276099.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686442/pexels-photo-35686442.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/5276099/pexels-photo-5276099.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Driver IC":"A4988","Max Current":"2A per coil","Min Logic Voltage":"3V","Max Motor Voltage":"35V","Microstepping":"Full, 1/2, 1/4, 1/8, 1/16","Dimensions":"20 x 15 mm","Weight":"3 g"}'::jsonb, ARRAY['Up to 2A per coil','5 step resolutions','Built-in translator','Adjustable current limit','Over-temperature protection'], ARRAY['1x A4988 Driver Module','1x Heatsink'], ARRAY['Arduino','Raspberry Pi','NEMA 17 motors','3D printers','CNC machines'], ARRAY['stepper driver','a4988','cnc','3d printer','motor driver'], 4.5, 78, 200, false, false, false, false, 3),
('12V DC Motor 200 RPM with Encoder', 'dc-motor-12v-200rpm', 'A 12V DC motor with 200 RPM speed and built-in encoder for precise speed and position control. Perfect for robotics, conveyor systems, and automation projects. Metal gearbox for durability.', '12V DC motor with encoder, 200 RPM', (SELECT id FROM categories WHERE slug='motors'), (SELECT id FROM brands WHERE slug='dfrobot'), 'MOT-DC-12V-200', 699.00, 999.00, ARRAY['https://images.pexels.com/photos/11579194/pexels-photo-11579194.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686432/pexels-photo-35686432.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/11579194/pexels-photo-11579194.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Rated Voltage":"12V","No-Load Speed":"200 RPM","Stall Torque":"5 kg-cm","Gear Ratio":"1:30","Encoder":"Yes (11PPR)","Shaft Diameter":"6 mm","Body Diameter":"37 mm","Length":"50 mm","Weight":"120 g"}'::jsonb, ARRAY['200 RPM speed','Built-in encoder','Metal gearbox','12V operation','5 kg-cm stall torque'], ARRAY['1x DC Motor with Encoder','1x Mounting Bracket','1x Wheel adapter'], ARRAY['Arduino with motor driver','ESP32 with motor driver','Raspberry Pi with motor driver'], ARRAY['dc motor','encoder','robotics','12v','gear motor'], 4.4, 34, 80, false, false, true, false, 120),
('28BYJ-48 Stepper Motor with ULN2003 Driver', '28byj-48-stepper-uln2003', 'A 5V unipolar stepper motor with ULN2003 driver board. Perfect for Arduino and robotics projects. Low cost and easy to use with included driver board.', '5V stepper motor with ULN2003 driver board', (SELECT id FROM categories WHERE slug='motors'), (SELECT id FROM brands WHERE slug='elegoo'), 'MOT-28BYJ-48', 199.00, 349.00, ARRAY['https://images.pexels.com/photos/11579194/pexels-photo-11579194.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686432/pexels-photo-35686432.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/11579194/pexels-photo-11579194.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Type":"Unipolar Stepper","Rated Voltage":"5V","Step Angle":"5.625 deg/step","Reduction Ratio":"1:64","In-traction Torque":"300 g-cm","Driver":"ULN2003","Phases":"4","Dimensions":"28 x 24 x 20 mm","Weight":"40 g"}'::jsonb, ARRAY['5V unipolar stepper','ULN2003 driver included','1:64 gear reduction','Low cost','Easy Arduino interface'], ARRAY['1x 28BYJ-48 Stepper Motor','1x ULN2003 Driver Board'], ARRAY['Arduino','ESP32','Raspberry Pi'], ARRAY['stepper','28byj-48','uln2003','motor','arduino','robotics'], 4.4, 67, 300, false, false, false, false, 40),
('0.96 inch OLED Display Module I2C', 'oled-display-096-i2c', 'A 0.96 inch monochrome OLED display with I2C interface. 128x64 pixel resolution with SSD1306 driver chip. Perfect for displaying sensor data, menus, and UI elements in your projects.', '128x64 OLED with SSD1306 I2C interface', (SELECT id FROM categories WHERE slug='displays'), (SELECT id FROM brands WHERE slug='waveshare'), 'DISP-OLED-096', 249.00, 399.00, ARRAY['https://images.pexels.com/photos/35686442/pexels-photo-35686442.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686430/pexels-photo-35686430.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686436/pexels-photo-35686436.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686442/pexels-photo-35686442.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Display":"OLED","Resolution":"128 x 64","Driver IC":"SSD1306","Interface":"I2C","Screen Size":"0.96 inch","Color":"White on Black","Operating Voltage":"3.3-5V","Viewing Angle":"160 degrees","Dimensions":"27 x 27 x 4 mm"}'::jsonb, ARRAY['128x64 resolution','I2C interface','No backlight needed','Low power consumption','3.3-5V compatible'], ARRAY['1x OLED Display Module','1x 4-pin header'], ARRAY['Arduino','ESP32','Raspberry Pi','STM32'], ARRAY['oled','display','i2c','ssd1306','128x64'], 4.5, 67, 250, false, false, true, false, 5),
('16x2 LCD Display with I2C Module', 'lcd-16x2-i2c', 'A 16x2 character LCD display with I2C backpack module. Blue backlight with white text. I2C interface reduces pin usage to just 2 wires. Perfect for displaying sensor data, menus, and project interfaces.', '16x2 character LCD with I2C backpack', (SELECT id FROM categories WHERE slug='displays'), (SELECT id FROM brands WHERE slug='waveshare'), 'DISP-LCD-1602-I2C', 199.00, 349.00, ARRAY['https://images.pexels.com/photos/35686442/pexels-photo-35686442.jpeg?auto=compress&cs=tinysrgb&h=650&w=940','https://images.pexels.com/photos/35686430/pexels-photo-35686430.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'], 'https://images.pexels.com/photos/35686442/pexels-photo-35686442.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '{"Display":"16x2 Character LCD","Backlight":"Blue","Text Color":"White","Driver":"HD44780","Interface":"I2C (PCF8574)","Address":"0x27 or 0x3F","Operating Voltage":"5V","Dimensions":"80 x 36 x 11 mm","Weight":"40 g"}'::jsonb, ARRAY['16x2 character display','I2C interface (2 pins)','Blue backlight','Adjustable contrast','HD44780 compatible'], ARRAY['1x 16x2 LCD Display','1x I2C Backpack (soldered)'], ARRAY['Arduino','ESP32','Raspberry Pi','PIC','STM32'], ARRAY['lcd','display','16x2','i2c','character display'], 4.5, 98, 200, false, false, false, false, 40)
